code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    tracks = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                steps = [(0, 1), (0, 1), (-1, 0)]
            elif color == 2:
                steps = [(0, -1)] * 4
            elif color == 3:
                steps = [(1, 0)] * 3
            elif color == 6:
                steps = [(-1, 0)] * 6
            else:
                continue
            cells = []
            rr, cc = r, c
            for dr, dc in steps:
                rr, cc = rr + dr, cc + dc
                if 0 <= rr < h and 0 <= cc < w:
                    cells.append((rr, cc))
            # The ray's terminal cell carries its source color; its interior is color 5.
            for i, (rr, cc) in enumerate(cells):
                if i == len(cells) - 1:
                    out[rr][cc] = color
                elif out[rr][cc] == 0:
                    out[rr][cc] = 5
            tracks.append(set(cells))

    # Crossings between rays become color 4.
    crossings = set()
    for i in range(len(tracks)):
        for j in range(i + 1, len(tracks)):
            crossings.update(tracks[i] & tracks[j])
    for r, c in crossings:
        out[r][c] = 4
    # Each collision emits a diagonal 4 ray down-left to the edge.
    for r, c in crossings:
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
'''
